('claim.v080.persephone_worshipped_eleusis','deity.greek.persephone','WORSHIPPED_AT','site.greece.eleusis',NULL,NULL,'The official archaeological record identifies Eleusis as the sanctuary of Demeter and Kore.','greek.eleusis.cult','SUPPORTED',0.99,'HIGH','VERIFIED','HISTORICAL_REALITY','ARCHAEOLOGICAL','Eleusinian cult','Ancient sanctuary history','Kore is mapped to the existing Persephone entity without deleting the Kore name layer.','2026-08-21T00:00:00Z'),
('claim.v080.mysteries_demeter','ritual.greek.eleusinian_mysteries','ASSOCIATED_WITH','deity.greek.demeter',NULL,NULL,'Public archaeological and museum scholarship associate the Eleusinian Mysteries with Demeter.','greek.eleusis.ritual','SUPPORTED',0.99,'HIGH','VERIFIED','HISTORICAL_REALITY','RITUAL_PRACTICE','Eleusinian ritual','Ancient practice','Association only; secret acts are not reconstructed.','2026-08-21T00:00:00Z'),
('claim.v080.mysteries_persephone','ritual.greek.eleusinian_mysteries','ASSOCIATED_WITH','deity.greek.persephone',NULL,NULL,'Public archaeological and museum scholarship associate the Eleusinian Mysteries with Persephone/Kore.','greek.eleusis.ritual','SUPPORTED',0.99,'HIGH','VERIFIED','HISTORICAL_REALITY','RITUAL_PRACTICE','Eleusinian ritual','Ancient practice','Kore and Persephone naming is retained at the source layer.','2026-08-21T00:00:00Z'),
('claim.v080.telesterion_part_eleusis','site.greece.eleusis_telesterion','PART_OF','site.greece.eleusis',NULL,NULL,'The Telesterion is modeled as a monument within the wider archaeological site and sanctuary of Eleusis.','greek.eleusis.structure','SUPPORTED',0.99,'HIGH','VERIFIED','HISTORICAL_REALITY','ARCHAEOLOGICAL','Eleusis','Multiple building phases','Subsite containment, not identity.','2026-08-21T00:00:00Z'),
('claim.v080.telesterion_mysteries','site.greece.eleusis_telesterion','ASSOCIATED_WITH','ritual.greek.eleusinian_mysteries',NULL,NULL,'Official heritage interpretation and museum scholarship identify the Telesterion as the central assembly hall for the mysteries.','greek.eleusis.telesterion','SUPPORTED',0.98,'HIGH','VERIFIED','HISTORICAL_REALITY','RITUAL_PRACTICE','Eleusinian ritual','Ancient practice','Only the public building-function layer is asserted.','2026-08-21T00:00:00Z'),
('claim.v080.sacredway_eleusis','site.greece.sacred_way','ASSOCIATED_WITH','site.greece.eleusis',NULL,NULL,'The official heritage record describes the Processional Road at Eleusis as continuing the Sacred Way from Athens.','greek.eleusis.route','SUPPORTED',0.99,'HIGH','VERIFIED','HISTORICAL_REALITY','ARCHAEOLOGICAL','Attica','Ancient route','Route geometry and monuments remain queued for expansion.','2026-08-21T00:00:00Z'),
